import * as React from "react";
import { PanelPortalProps } from "./PanelPortal";
export type { PanelPosition, PanelSize } from "./PanelPortal";
export interface PanelProps extends PanelPortalProps {
    /**
     * If the panel is open.
     *
     * @default false
     */
    isOpen?: boolean;
}
/**
 * A panel provides supplemental information or form inputs that relate to your primary canvas.
 *
 * - {@link https://livingdesign.walmart.com/components/panel/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/panel/react/ React documentation}
 *
 * ### Actions
 *
 * The Panel accepts actions through the `actions` prop:
 *
 * ```tsx
 * <Panel
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action1</Button>
 *       <Button>Action2</Button>
 *     </ButtonGroup>
 *   }
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Panel>
 * ```
 *
 * ### Content
 *
 * The Panel accepts content through the `children` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Panel>
 * ```
 *
 * ### Opening and closing
 *
 * The Panel is open based on the `isOpen` property. Add an `onClose` callback that configures `isOpen` state when the Panel requests to close.
 *
 * ```tsx
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *
 *   return (
 *     <>
 *       <Button onClick={() => setIsOpen(true)}>
 *         Open panel
 *       </Button>
 *
 *       <Panel
 *         isOpen={isOpen}
 *         onClose={() => setIsOpen(false)}
 *         title="Title"
 *       >
 *         Content
 *       </Panel>
 *     </>
 *   );
 * };
 * ```
 *
 * ### Position
 *
 * The Panel has two different positions. Set the position through the `position` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   position="left"
 *   title="Title"
 * >
 *   Left
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   position="right"
 *   title="Title"
 * >
 *   Right
 * </Panel>
 * ```
 *
 * ### Size
 *
 * The Panel comes in three sizes. Set the size with the `size` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="small"
 *   title="Title"
 * >
 *   Small
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="medium"
 *   title="Title"
 * >
 *   Medium
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="large"
 *   title="Title"
 * >
 *   Large
 * </Panel>
 * ```
 *
 * ### Title
 *
 * Set the title of the Panel with the `title` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Panel
 * </Panel>
 * ```
 */
export declare const Panel: React.FunctionComponent<PanelProps>;
